begin;
set local role postgres;
create extension if not exists pgtap with schema extensions;
set local search_path=pgtap,extensions,public;
select plan(36);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values
('00000000-0000-4000-8000-00000000300a','00000000-0000-0000-0000-000000000000','authenticated','authenticated','proc-owner@example.test','',now(),now(),now()),
('00000000-0000-4000-8000-00000000300b','00000000-0000-0000-0000-000000000000','authenticated','authenticated','proc-other@example.test','',now(),now(),now());
set local role authenticated; select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000300a","role":"authenticated"}',true);
select lives_ok($$select public.create_organization('Procurement A','procurement-a','GB','GBP','Europe/London')$$,'procurement tenant bootstraps');
set local role postgres; select set_config('p.org',(select id::text from public.organizations where slug='procurement-a'),true); select set_config('p.business',(select id::text from public.businesses where organization_id=current_setting('p.org')::uuid limit 1),true); select set_config('p.unit',(select id::text from public.units_of_measure where organization_id=current_setting('p.org')::uuid and name='Piece'),true);
insert into public.branches(id,organization_id,business_id,name,code,status,timezone,created_by) values('00000000-0000-4000-8000-000000003101',current_setting('p.org')::uuid,current_setting('p.business')::uuid,'Proc Branch','PROC','active','Europe/London','00000000-0000-4000-8000-00000000300a');
insert into public.warehouses(id,organization_id,business_id,branch_id,name,code,status,warehouse_type,created_by) values('00000000-0000-4000-8000-000000003201',current_setting('p.org')::uuid,current_setting('p.business')::uuid,'00000000-0000-4000-8000-000000003101','Proc Main','PROC-M','active','MAIN','00000000-0000-4000-8000-00000000300a');
select set_config('p.loc',(select id::text from public.storage_locations where warehouse_id='00000000-0000-4000-8000-000000003201' limit 1),true);
set local role authenticated; select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000300a","role":"authenticated"}',true); select set_config('p.product',(select public.create_simple_product(current_setting('p.org')::uuid,current_setting('p.business')::uuid,'Proc Item','STOCKED_PRODUCT',null,null,null,current_setting('p.unit')::uuid,'PROC-1','',null,null,null,null,true,gen_random_uuid())::text),true);
set local role postgres; select set_config('p.variant',(select id::text from public.product_variants where product_id=current_setting('p.product')::uuid),true); select set_config('p.package',(select id::text from public.product_variant_packaging where product_variant_id=current_setting('p.variant')::uuid and is_base_unit),true);
insert into public.approval_policies(id,organization_id,name,document_type,branch_id,minimum_amount,currency,prohibit_self_approval,created_by) values('00000000-0000-4000-8000-000000003250',current_setting('p.org')::uuid,'Requisition approval','REQUISITION','00000000-0000-4000-8000-000000003101',0,'GBP',true,'00000000-0000-4000-8000-00000000300a');
insert into public.approval_steps(organization_id,policy_id,step_order,permission_code) values(current_setting('p.org')::uuid,'00000000-0000-4000-8000-000000003250',1,'procurement.requisition_approve');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000300a","role":"authenticated"}',true);
select set_config('p.supplier',(select public.create_supplier(current_setting('p.org')::uuid,'SUP-1','DISTRIBUTOR','Supplier One','','supplier@example.test','', 'GBP','30 days','')::text),true);
select is((select status from public.suppliers where id=current_setting('p.supplier')::uuid),'ACTIVE','supplier created active');
select lives_ok(format($q$select public.add_supplier_product('%s','%s','%s','%s','S-ITEM','Supplier item',1,1,3,true)$q$,current_setting('p.org'),current_setting('p.supplier'),current_setting('p.variant'),current_setting('p.package')),'supplier product association created');
select is((select count(*) from public.supplier_products where supplier_id=current_setting('p.supplier')::uuid),1::bigint,'supplier product persisted');
select throws_ok(format($q$select public.add_supplier_product('%s','%s','%s','%s','BAD','Bad',1,1,1,false)$q$,current_setting('p.org'),current_setting('p.supplier'),gen_random_uuid(),current_setting('p.package')),'P0001','INVALID_PACKAGING','cross product packaging rejected');
select set_config('p.req',(select public.create_purchase_requisition(current_setting('p.org')::uuid,current_setting('p.business')::uuid,'00000000-0000-4000-8000-000000003101',current_date+7,'NORMAL','Operations','Restock',jsonb_build_array(jsonb_build_object('product_variant_id',current_setting('p.variant'),'packaging_id',current_setting('p.package'),'quantity',10,'estimated_unit_cost',10)))::text),true);
select is((select status from public.purchase_requisitions where id=current_setting('p.req')::uuid),'DRAFT','requisition starts draft');
select is((select requested_base_quantity from public.purchase_requisition_lines where requisition_id=current_setting('p.req')::uuid),10::numeric,'requisition snapshots base quantity');
select lives_ok(format($q$select public.submit_purchase_requisition('%s','%s','00000000-0000-4000-8000-000000003301')$q$,current_setting('p.org'),current_setting('p.req')),'requisition submits');
select is((select status from public.purchase_requisitions where id=current_setting('p.req')::uuid),'PENDING_APPROVAL','requisition pending approval');
select set_config('p.approval',(select id::text from public.approval_requests where document_id=current_setting('p.req')::uuid),true);
select throws_ok(format($q$select public.act_on_approval('%s','%s','APPROVE','Self')$q$,current_setting('p.org'),current_setting('p.approval')),'42501','SELF_APPROVAL_DENIED','self approval denied when policy says so');
-- The default/no-policy path permits owner approval; assign another authorized owner for deterministic approval.
set local role postgres; insert into public.organization_members(organization_id,user_id,status,joined_at) values(current_setting('p.org')::uuid,'00000000-0000-4000-8000-00000000300b','active',now()); insert into public.member_roles(organization_id,membership_id,role_id) select current_setting('p.org')::uuid,m.id,r.id from public.organization_members m join public.roles r on r.organization_id=m.organization_id and r.name='Owner' where m.user_id='00000000-0000-4000-8000-00000000300b';
set local role authenticated; select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000300b","role":"authenticated"}',true);
select lives_ok(format($q$select public.act_on_approval('%s','%s','APPROVE','Approved')$q$,current_setting('p.org'),current_setting('p.approval')),'authorized approval succeeds');
select is((select status from public.purchase_requisitions where id=current_setting('p.req')::uuid),'APPROVED','requisition approved');
select throws_ok(format($q$select public.act_on_approval('%s','%s','APPROVE','Again')$q$,current_setting('p.org'),current_setting('p.approval')),'42501','APPROVAL_NOT_AVAILABLE','double approval blocked');
select set_config('p.po',(select public.create_purchase_order(current_setting('p.org')::uuid,current_setting('p.business')::uuid,current_setting('p.supplier')::uuid,'00000000-0000-4000-8000-000000003101','00000000-0000-4000-8000-000000003201',current_setting('p.loc')::uuid,current_date,current_date+3,'GBP',1,'30 days','Test PO',jsonb_build_array(jsonb_build_object('product_variant_id',current_setting('p.variant'),'packaging_id',current_setting('p.package'),'quantity',10,'unit_price',10,'discount',0,'tax',0)))::text),true);
select is((select total from public.purchase_orders where id=current_setting('p.po')::uuid),100::numeric,'PO total calculated');
select is((select base_currency_total from public.purchase_orders where id=current_setting('p.po')::uuid),100::numeric,'PO currency snapshot converted');
select lives_ok(format($q$select public.approve_purchase_order('%s','%s','00000000-0000-4000-8000-000000003401')$q$,current_setting('p.org'),current_setting('p.po')),'PO approves');
select throws_ok(format($q$update public.purchase_orders set total=50 where id='%s'$q$,current_setting('p.po')),'42501',null,'direct approved PO update denied');
select set_config('p.poline',(select id::text from public.purchase_order_lines where purchase_order_id=current_setting('p.po')::uuid),true);
select lives_ok(format($q$select public.post_goods_receipt('%s','%s','DN-1',now(),'Partial','00000000-0000-4000-8000-000000003501',false,'',jsonb_build_array(jsonb_build_object('purchase_order_line_id','%s','delivered_quantity',4,'accepted_quantity',4,'rejected_quantity',0)))$q$,current_setting('p.org'),current_setting('p.po'),current_setting('p.poline')),'partial GRN posts');
select is((select status from public.purchase_orders where id=current_setting('p.po')::uuid),'PARTIALLY_RECEIVED','PO partial state');
select is((select on_hand_base_quantity from public.inventory_balances where product_variant_id=current_setting('p.variant')::uuid),4::numeric,'receipt increases inventory');
select is((select transaction_type from public.inventory_transactions where reference_type='PURCHASE_RECEIPT' and reference_id in(select id from public.goods_receipts where purchase_order_id=current_setting('p.po')::uuid)),'PURCHASE_RECEIPT','receipt uses inventory ledger');
select lives_ok(format($q$select public.post_goods_receipt('%s','%s','DN-1',now(),'Partial','00000000-0000-4000-8000-000000003501',false,'',jsonb_build_array(jsonb_build_object('purchase_order_line_id','%s','delivered_quantity',4,'accepted_quantity',4,'rejected_quantity',0)))$q$,current_setting('p.org'),current_setting('p.po'),current_setting('p.poline')),'duplicate GRN replays');
select is((select count(*) from public.goods_receipts where purchase_order_id=current_setting('p.po')::uuid),1::bigint,'idempotent receipt creates one GRN');
select throws_ok(format($q$select public.post_goods_receipt('%s','%s','DN-X',now(),'Over',gen_random_uuid(),false,'',jsonb_build_array(jsonb_build_object('purchase_order_line_id','%s','delivered_quantity',7,'accepted_quantity',7,'rejected_quantity',0)))$q$,current_setting('p.org'),current_setting('p.po'),current_setting('p.poline')),'P0001','OVER_RECEIPT_NOT_ALLOWED','over receipt blocked');
select lives_ok(format($q$select public.post_goods_receipt('%s','%s','DN-2',now(),'Remainder','00000000-0000-4000-8000-000000003502',false,'',jsonb_build_array(jsonb_build_object('purchase_order_line_id','%s','delivered_quantity',6,'accepted_quantity',6,'rejected_quantity',0)))$q$,current_setting('p.org'),current_setting('p.po'),current_setting('p.poline')),'remainder GRN posts');
select is((select status from public.purchase_orders where id=current_setting('p.po')::uuid),'FULLY_RECEIVED','PO fully received cumulatively');
select is((select on_hand_base_quantity from public.inventory_balances where product_variant_id=current_setting('p.variant')::uuid),10::numeric,'cumulative receipt balance correct');
select is((select average_unit_cost from public.inventory_balances where product_variant_id=current_setting('p.variant')::uuid),10::numeric,'WAC receives base currency unit cost');
select set_config('p.grn',(select id::text from public.goods_receipts where idempotency_key='00000000-0000-4000-8000-000000003502'),true);
select set_config('p.return',(select public.post_purchase_return(current_setting('p.org')::uuid,current_setting('p.business')::uuid,current_setting('p.supplier')::uuid,current_setting('p.po')::uuid,current_setting('p.grn')::uuid,'00000000-0000-4000-8000-000000003101',current_setting('p.loc')::uuid,'DEFECTIVE','Defect','00000000-0000-4000-8000-000000003601',jsonb_build_array(jsonb_build_object('product_variant_id',current_setting('p.variant'),'packaging_id',current_setting('p.package'),'quantity',2,'unit_cost_base',10)))->>'purchase_return_id'),true);
select is((select on_hand_base_quantity from public.inventory_balances where product_variant_id=current_setting('p.variant')::uuid),8::numeric,'purchase return reduces inventory');
select is((select transaction_type from public.inventory_transactions where reference_type='PURCHASE_RETURN' and reference_id=current_setting('p.return')::uuid),'PURCHASE_RETURN','return uses inventory ledger');
select set_config('p.invoice',(select public.record_supplier_invoice(current_setting('p.org')::uuid,current_setting('p.supplier')::uuid,'INV-1',current_date,current_date+30,'GBP',1,100,0,0,0,100,'',array[current_setting('p.po')::uuid],array[current_setting('p.grn')::uuid])::text),true);
select is((select match_status from public.supplier_invoices where id=current_setting('p.invoice')::uuid),'MATCHED','invoice matches PO total');
select throws_ok(format($q$select public.record_supplier_invoice('%s','%s','INV-1',current_date,current_date+30,'GBP',1,100,0,0,0,100,'',array['%s'::uuid],array['%s'::uuid])$q$,current_setting('p.org'),current_setting('p.supplier'),current_setting('p.po'),current_setting('p.grn')),'23505',null,'duplicate supplier invoice blocked');
select lives_ok(format($q$select public.approve_supplier_invoice('%s','%s')$q$,current_setting('p.org'),current_setting('p.invoice')),'supplier invoice approves');
select is((select outstanding_base from public.supplier_payables where supplier_id=current_setting('p.supplier')::uuid),100::numeric,'payable derived from approved invoice');
select throws_ok(format($q$update public.inventory_balances set on_hand_base_quantity=999 where organization_id='%s'$q$,current_setting('p.org')),'42501',null,'procurement user cannot mutate balances');
select throws_ok(format($q$insert into public.inventory_movements(id,organization_id,transaction_id,product_variant_id,branch_id,warehouse_id,storage_location_id,movement_type,quantity_delta_base,entered_quantity,packaging_id,conversion_to_base_snapshot,valuation_unit_cost,valuation_total,costing_method_snapshot,occurred_at,posted_at) values(gen_random_uuid(),'%s',gen_random_uuid(),'%s','00000000-0000-4000-8000-000000003101','00000000-0000-4000-8000-000000003201','%s','PURCHASE_RECEIPT',1,1,'%s',1,1,1,'WEIGHTED_AVERAGE',now(),now())$q$,current_setting('p.org'),current_setting('p.variant'),current_setting('p.loc'),current_setting('p.package')),'42501',null,'procurement user cannot insert movements');
select * from finish(); rollback;
